132		if !validID(id) {
133			writeError(w, http.StatusBadRequest, "invalid_request")
134			return
135		}
136		s.mu.RLock()
137		p, ok := s.pools[id]
138		var v poolView
139		if ok {
140			v = p.view()
141		}
142		s.mu.RUnlock()
