150	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
151		var in createPoolInput
152		if !decodeRequest(r, &in) {
153			writeError(w, http.StatusBadRequest, "invalid_request")
154			return
155		}
156		// Validate the whole payload before touching any state so a failure
157		// never leaves a partial pool behind.
158		if !validID(in.ID) || len(in.Devices) == 0 {
159			writeError(w, http.StatusBadRequest, "invalid_request")
160			return
161		}
162		seen := make(map[string]bool, len(in.Devices))
163		var rawCapacity int64
164		for _, d := range in.Devices {
165			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
166				writeError(w, http.StatusBadRequest, "invalid_request")
167				return
168			}
169			if rawCapacity > math.MaxInt64-d.CapacityBytes {
170				writeError(w, http.StatusBadRequest, "invalid_request")
171				return
172			}
173			seen[d.ID] = true
174			rawCapacity += d.CapacityBytes
175		}
176	
177		s.mu.Lock()
178		defer s.mu.Unlock()
179		if _, ok := s.pools[in.ID]; ok {
180			writeError(w, http.StatusConflict, "pool_exists")
181			return
182		}
183		for _, d := range in.Devices {
184			if _, busy := s.deviceOwner[d.ID]; busy {
185				writeError(w, http.StatusConflict, "device_in_use")
186				return
187			}
188		}
189	
190		devices := append([]deviceInput(nil), in.Devices...)
191		p := &pool{
192			id:           in.ID,
193			devices:      devices,
194			rawCapacity:  rawCapacity,
195			reservations: make(map[string]reservation),
196		}
197		s.pools[in.ID] = p
198		for _, d := range devices {
199			s.deviceOwner[d.ID] = in.ID
200		}
201		writeJSON(w, http.StatusCreated, p.view())
202	}
203	
204	func (s *store) deletePool(w http.ResponseWriter, id string) {
205		if !validID(id) {
206			writeError(w, http.StatusBadRequest, "invalid_request")
207			return
208		}
209		s.mu.Lock()
210		defer s.mu.Unlock()
211		p, ok := s.pools[id]
212		if !ok {
213			writeError(w, http.StatusNotFound, "pool_not_found")
214			return
215		}
216		if len(p.reservations) > 0 || p.volumeBytes > 0 {
217			writeError(w, http.StatusConflict, "pool_not_empty")
218			return
219		}
220		for _, d := range p.devices {
221			delete(s.deviceOwner, d.ID)
222		}
223		delete(s.pools, id)
224		w.WriteHeader(http.StatusNoContent)
225	}
226	
227	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
228		var in reservationInput
229		if !decodeRequest(r, &in) {
230			writeError(w, http.StatusBadRequest, "invalid_request")
231			return
232		}
233		if !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
234			writeError(w, http.StatusBadRequest, "invalid_request")
235			return
236		}
237	
238		s.mu.Lock()
239		defer s.mu.Unlock()
240		p, ok := s.pools[poolID]
241		if !ok {
242			writeError(w, http.StatusNotFound, "pool_not_found")
243			return
244		}
245		if existing, dup := p.reservations[in.RequestID]; dup {
246			if existing.bytes != in.Bytes {
247				writeError(w, http.StatusConflict, "idempotency_conflict")
248				return
249			}
250			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
251			return
252		}
253		allocated := p.allocated()
254		if allocated > p.rawCapacity-in.Bytes {
255			writeError(w, http.StatusConflict, "insufficient_capacity")
256			return
257		}
258		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes}
259		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
260	}
261	
262	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
263		if !validID(poolID) || !validID(requestID) {
264			writeError(w, http.StatusBadRequest, "invalid_request")
265			return
266		}
267		s.mu.Lock()
268		defer s.mu.Unlock()
269		p, ok := s.pools[poolID]
270		if !ok {
271			writeError(w, http.StatusNotFound, "pool_not_found")
272			return
273		}
274		// Deleting an unknown or already-deleted reservation is a success.
275		delete(p.reservations, requestID)
276		w.WriteHeader(http.StatusNoContent)
277	}
