1	package server
2	
3	import (
4		"net/http"
5		"net/url"
6		"sort"
7		"strconv"
8		"strings"
9	)
10	
11	type createVolumeInput struct {
12		ID        string `json:"id"`
13		PoolID    string `json:"poolId"`
14		SizeBytes int64  `json:"sizeBytes"`
15	}
16	
17	type bindingInput struct {
18		NodeID             string `json:"nodeId"`
19		ExpectedGeneration *int64 `json:"expectedGeneration"`
20	}
21	
22	// bindingView is the public representation of a volume binding.
23	type bindingView struct {
24		NodeID string `json:"nodeId"`
25	}
26	
27	// volumeView is the public representation of a volume.
28	type volumeView struct {
29		ID         string       `json:"id"`
30		PoolID     string       `json:"poolId"`
31		SizeBytes  int64        `json:"sizeBytes"`
32		Generation int64        `json:"generation"`
33		Binding    *bindingView `json:"binding"`
34	}
35	
36	func (v *volume) view() volumeView {
37		view := volumeView{
38			ID:         v.id,
39			PoolID:     v.poolID,
40			SizeBytes:  v.sizeBytes,
41			Generation: v.generation,
42			Binding:    nil,
43		}
44		if v.binding != "" {
45			view.Binding = &bindingView{NodeID: v.binding}
46		}
47		return view
48	}
49	
50	// routeVolumes dispatches /v1/volumes and its sub-paths.
51	func (s *store) routeVolumes(w http.ResponseWriter, r *http.Request) {
52		parts := splitPath(r.URL.Path, volumePath)
53		for _, seg := range parts {
54			if seg == "" {
55				writeError(w, http.StatusNotFound, "not_found")
56				return
57			}
58		}
59		switch {
60		case len(parts) == 0:
61			switch r.Method {
62			case http.MethodGet:
63				s.listVolumes(w)
64			case http.MethodPost:
65				s.createVolume(w, r)
66			default:
67				methodNotAllowed(w, http.MethodGet, http.MethodPost)
68			}
69		case len(parts) == 1:
70			switch r.Method {
71			case http.MethodGet:
72				s.getVolume(w, parts[0])
73			case http.MethodDelete:
74				s.deleteVolume(w, parts[0])
75			default:
76				methodNotAllowed(w, http.MethodGet, http.MethodDelete)
77			}
78		case len(parts) == 2 && parts[1] == "binding":
79			switch r.Method {
80			case http.MethodPut:
81				s.putBinding(w, r, parts[0])
82			case http.MethodDelete:
83				s.deleteBinding(w, r, parts[0])
84			default:
85				methodNotAllowed(w, http.MethodPut, http.MethodDelete)
86			}
87		default:
88			writeError(w, http.StatusNotFound, "not_found")
89		}
90	}
91	
92	func (s *store) listVolumes(w http.ResponseWriter) {
93		s.mu.RLock()
94		defer s.mu.RUnlock()
95		ids := make([]string, 0, len(s.volumes))
96		for id := range s.volumes {
97			ids = append(ids, id)
98		}
99		sort.Strings(ids)
100		items := make([]volumeView, 0, len(ids))
101		for _, id := range ids {
102			items = append(items, s.volumes[id].view())
103		}
104		writeJSON(w, http.StatusOK, map[string]any{"items": items})
105	}
106	
107	func (s *store) getVolume(w http.ResponseWriter, id string) {
108		if !validID(id) {
109			writeError(w, http.StatusBadRequest, "invalid_request")
110			return
111		}
112		s.mu.RLock()
113		v, ok := s.volumes[id]
114		var view volumeView
115		if ok {
116			view = v.view()
117		}
118		s.mu.RUnlock()
119		if !ok {
120			writeError(w, http.StatusNotFound, "volume_not_found")
121			return
122		}
123		writeJSON(w, http.StatusOK, view)
124	}
125	
126	func (s *store) createVolume(w http.ResponseWriter, r *http.Request) {
127		var in createVolumeInput
128		if !decodeRequest(r, &in) {
129			writeError(w, http.StatusBadRequest, "invalid_request")
130			return
131		}
132		if !validID(in.ID) || !validID(in.PoolID) || in.SizeBytes <= 0 {
133			writeError(w, http.StatusBadRequest, "invalid_request")
134			return
135		}
136	
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if existing, dup := s.volumes[in.ID]; dup {
140			if existing.poolID == in.PoolID && existing.sizeBytes == in.SizeBytes {
141				writeJSON(w, http.StatusOK, existing.view())
142				return
143			}
144			writeError(w, http.StatusConflict, "volume_exists")
145			return
146		}
147		p, ok := s.pools[in.PoolID]
148		if !ok {
149			writeError(w, http.StatusNotFound, "pool_not_found")
150			return
151		}
152		// Holding the store lock makes the capacity check and the reservation
153		// atomic, so concurrent creates can never overcommit the pool.
154		if p.allocated() > p.rawCapacity-in.SizeBytes {
155			writeError(w, http.StatusConflict, "insufficient_capacity")
156			return
157		}
158		v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: in.SizeBytes}
159		s.volumes[in.ID] = v
160		p.volumeBytes += in.SizeBytes
161		writeJSON(w, http.StatusCreated, v.view())
162	}
163	
164	func (s *store) deleteVolume(w http.ResponseWriter, id string) {
165		if !validID(id) {
166			writeError(w, http.StatusBadRequest, "invalid_request")
167			return
168		}
169		s.mu.Lock()
170		defer s.mu.Unlock()
