package server

import (
	"net/http"
	"net/url"
	"sort"
	"strconv"
	"strings"
)

type createVolumeInput struct {
	ID        string `json:"id"`
	PoolID    string `json:"poolId"`
	SizeBytes int64  `json:"sizeBytes"`
}

type bindingInput struct {
	NodeID             string `json:"nodeId"`
	ExpectedGeneration *int64 `json:"expectedGeneration"`
}

// bindingView is the public representation of a volume binding.
type bindingView struct {
	NodeID string `json:"nodeId"`
}

// volumeView is the public representation of a volume.
type volumeView struct {
	ID         string       `json:"id"`
	PoolID     string       `json:"poolId"`
	SizeBytes  int64        `json:"sizeBytes"`
	Generation int64        `json:"generation"`
	Binding    *bindingView `json:"binding"`
}

func (v *volume) view() volumeView {
	view := volumeView{
		ID:         v.id,
		PoolID:     v.poolID,
		SizeBytes:  v.sizeBytes,
		Generation: v.generation,
		Binding:    nil,
	}
	if v.binding != "" {
		view.Binding = &bindingView{NodeID: v.binding}
	}
	return view
}

// routeVolumes dispatches /v1/volumes and its sub-paths.
func (s *store) routeVolumes(w http.ResponseWriter, r *http.Request) {
	parts := splitPath(r.URL.Path, volumePath)
	for _, seg := range parts {
		if seg == "" {
			writeError(w, http.StatusNotFound, "not_found")
			return
		}
	}
	switch {
	case len(parts) == 0:
		switch r.Method {
		case http.MethodGet:
			s.listVolumes(w)
		case http.MethodPost:
			s.createVolume(w, r)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPost)
		}
	case len(parts) == 1:
		switch r.Method {
		case http.MethodGet:
			s.getVolume(w, parts[0])
		case http.MethodDelete:
			s.deleteVolume(w, parts[0])
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "binding":
		switch r.Method {
		case http.MethodPut:
			s.putBinding(w, r, parts[0])
		case http.MethodDelete:
			s.deleteBinding(w, r, parts[0])
		default:
			methodNotAllowed(w, http.MethodPut, http.MethodDelete)
		}
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

func (s *store) listVolumes(w http.ResponseWriter) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	ids := make([]string, 0, len(s.volumes))
	for id := range s.volumes {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	items := make([]volumeView, 0, len(ids))
	for _, id := range ids {
		items = append(items, s.volumes[id].view())
	}
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

func (s *store) getVolume(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.RLock()
	v, ok := s.volumes[id]
	var view volumeView
	if ok {
		view = v.view()
	}
	s.mu.RUnlock()
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	writeJSON(w, http.StatusOK, view)
}

func (s *store) createVolume(w http.ResponseWriter, r *http.Request) {
	var in createVolumeInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(in.ID) || !validID(in.PoolID) || in.SizeBytes <= 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	if existing, dup := s.volumes[in.ID]; dup {
		if existing.poolID == in.PoolID && existing.sizeBytes == in.SizeBytes {
			writeJSON(w, http.StatusOK, existing.view())
			return
		}
		writeError(w, http.StatusConflict, "volume_exists")
		return
	}
	p, ok := s.pools[in.PoolID]
	if !ok {
		writeError(w, http.StatusNotFound, "pool_not_found")
		return
	}
	// Holding the store lock makes the capacity check and the reservation
	// atomic, so concurrent creates can never overcommit the pool.
	if p.allocated() > p.rawCapacity-in.SizeBytes {
		writeError(w, http.StatusConflict, "insufficient_capacity")
		return
	}
	v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: in.SizeBytes}
	s.volumes[in.ID] = v
	p.volumeBytes += in.SizeBytes
	writeJSON(w, http.StatusCreated, v.view())
}

func (s *store) deleteVolume(w http.ResponseWriter, id string) {
	if !validID(id) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.volumes[id]
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.binding != "" {
		writeError(w, http.StatusConflict, "volume_in_use")
		return
	}
	s.pools[v.poolID].volumeBytes -= v.sizeBytes
	delete(s.volumes, id)
	w.WriteHeader(http.StatusNoContent)
}

func (s *store) putBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
	var in bindingInput
	if !decodeRequest(r, &in) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	if !validID(volumeID) || !validID(in.NodeID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}
	expected := *in.ExpectedGeneration

	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.volumes[volumeID]
	if !ok {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.generation != expected {
		writeError(w, http.StatusConflict, "stale_generation")
		return
	}
	switch {
	case v.binding == "":
		v.binding = in.NodeID
		v.generation++
	case v.binding != in.NodeID:
		writeError(w, http.StatusConflict, "volume_already_bound")
		return
	}
	// A same-node, same-generation PUT is an idempotent no-op that returns
	// the current representation without bumping the generation.
	writeJSON(w, http.StatusOK, v.view())
}

func (s *store) deleteBinding(w http.ResponseWriter, r *http.Request, volumeID string) {
	// expectedGeneration is the single accepted query parameter; it must be
	// present exactly once. Parse the raw string manually so malformed or
	// duplicated parameters cannot be silently discarded.
	gen, ok := parseGenerationQuery(r.URL.RawQuery)
	if !ok || !validID(volumeID) {
		writeError(w, http.StatusBadRequest, "invalid_request")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	v, exists := s.volumes[volumeID]
	if !exists {
		writeError(w, http.StatusNotFound, "volume_not_found")
		return
	}
	if v.generation != gen {
		writeError(w, http.StatusConflict, "stale_generation")
		return
	}
	wasBound := v.binding != ""
	v.binding = ""
	if wasBound {
		v.generation++
	}
	w.WriteHeader(http.StatusNoContent)
}

// parseGenerationQuery accepts exactly one "expectedGeneration=<non-neg-int>"
// pair. Missing, empty, duplicated or extra parameters yield ok=false.
func parseGenerationQuery(raw string) (int64, bool) {
	if raw == "" {
		return 0, false
	}
	var gen int64
	found := false
	for _, pair := range strings.Split(raw, "&") {
		key, value, ok := strings.Cut(pair, "=")
		if !ok {
			return 0, false
		}
		decodedKey, err := url.QueryUnescape(key)
		if err != nil {
			return 0, false
		}
		if decodedKey != "expectedGeneration" {
			return 0, false
		}
		if found {
			return 0, false
		}
		decodedValue, err := url.QueryUnescape(value)
		if err != nil {
			return 0, false
		}
		parsed, err := strconv.ParseInt(decodedValue, 10, 64)
		if err != nil || parsed < 0 {
			return 0, false
		}
		gen, found = parsed, true
	}
	return gen, found
}

// Package server exposes the frozen public surface of VaultGrid.
//
// In addition to process health, it serves the storage-pool, capacity
// reservation and volume lifecycle HTTP API described in README.md. The
// exported surface (Handler, Version, VAULTGRID_ADDR handling) stays
// backward compatible.
package server

import (
	"encoding/json"
	"io"
	"net/http"
	"regexp"
	"strings"
)

// Version is the release identifier.
const Version = "0.1.0"

// idPattern restricts every client-supplied id: 1..64 letters, digits,
// dots, underscores or hyphens.
var idPattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)

type health struct {
	Status  string `json:"status"`
	Service string `json:"service"`
	Version string `json:"version"`
}

// Handler returns the HTTP surface served by VaultGrid.
func Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "vaultgrid", Version: Version})
	})
	mux.HandleFunc("/", newStore().route)
	return mux
}

const (
	storagePoolPath = "/v1/storage-pools"
	volumePath      = "/v1/volumes"
)

// route dispatches every non-healthz request. Paths it does not recognise
// answer 404/not_found; recognised paths with the wrong verb answer 405.
func (s *store) route(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.URL.Path == volumePath || strings.HasPrefix(r.URL.Path, volumePath+"/"):
		s.routeVolumes(w, r)
	case r.URL.Path == storagePoolPath || strings.HasPrefix(r.URL.Path, storagePoolPath+"/"):
		s.routeStoragePools(w, r)
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

// routeStoragePools dispatches /v1/storage-pools and its sub-paths.
func (s *store) routeStoragePools(w http.ResponseWriter, r *http.Request) {
	parts := splitPath(r.URL.Path, storagePoolPath)
	for _, seg := range parts {
		if seg == "" {
			writeError(w, http.StatusNotFound, "not_found")
			return
		}
	}
	switch {
	case len(parts) == 0:
		switch r.Method {
		case http.MethodGet:
			s.listPools(w)
		case http.MethodPost:
			s.createPool(w, r)
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodPost)
		}
	case len(parts) == 1:
		switch r.Method {
		case http.MethodGet:
			s.getPool(w, parts[0])
		case http.MethodDelete:
			s.deletePool(w, parts[0])
		default:
			methodNotAllowed(w, http.MethodGet, http.MethodDelete)
		}
	case len(parts) == 2 && parts[1] == "reservations":
		if r.Method != http.MethodPost {
			methodNotAllowed(w, http.MethodPost)
			return
		}
		s.createReservation(w, r, parts[0])
	case len(parts) == 3 && parts[1] == "reservations":
		if r.Method != http.MethodDelete {
			methodNotAllowed(w, http.MethodDelete)
			return
		}
		s.deleteReservation(w, parts[0], parts[2])
	default:
		writeError(w, http.StatusNotFound, "not_found")
	}
}

// splitPath splits the tail after prefix into path segments.
func splitPath(path, prefix string) []string {
	rest := strings.TrimPrefix(path, prefix)
	if rest == "" {
		return nil
	}
	segments := strings.Split(rest, "/")
	// Drop the single empty segment introduced by the leading slash, but
	// keep trailing/inner empty segments so the caller can reject them 404.
	if segments[0] == "" {
		segments = segments[1:]
	}
	return segments
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code string) {
	writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
}

// decodeRequest parses exactly one JSON value, rejecting unknown fields and
// any trailing content so malformed bodies cannot partially apply.
func decodeRequest(r *http.Request, v any) bool {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return false
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		return false
	}
	return true
}

