1	package server
2	
3	import (
4		"fmt"
5		"net/http"
6		"net/http/httptest"
7		"sync"
8		"testing"
9	)
10	
11	const volPool = `{"id":"vp","devices":[{"id":"vdev","capacityBytes":1000,"faultDomain":"rack1"}]}`
12	
13	func createVol(t *testing.T, h http.Handler, body string) *httptest.ResponseRecorder {
14		t.Helper()
15		rec := do(h, http.MethodPost, "/v1/volumes", body)
16		if rec.Code != http.StatusCreated {
17			t.Fatalf("create volume status = %d body = %s", rec.Code, rec.Body.String())
18		}
19		return rec
20	}
21	
22	func TestCreateVolumeRepresentation(t *testing.T) {
23		h := Handler()
24		createPool(t, h, volPool)
25	
26		rec := createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":300}`)
27		v := decodeBody(t, rec)
28		if v["id"] != "vol1" || v["poolId"] != "vp" || v["sizeBytes"].(float64) != 300 {
29			t.Fatalf("volume view = %v", v)
30		}
31		if v["generation"].(float64) != 0 {
32			t.Fatalf("initial generation = %v", v["generation"])
33		}
34		if binding, ok := v["binding"]; !ok || binding != nil {
35			t.Fatalf("initial binding = %v", binding)
36		}
37	
38		// Volume size counts toward the owning pool's allocation.
39		p := decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/vp", ""))
40		if p["allocatedBytes"].(float64) != 300 || p["availableBytes"].(float64) != 700 {
41			t.Fatalf("pool after volume = %v", p)
42		}
43	}
44	
45	func TestCreateVolumeIdempotencyAndConflicts(t *testing.T) {
46		h := Handler()
47		createPool(t, h, volPool)
48		createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":300}`)
49	
50		// Identical retry: 200, same representation, no double count.
51		rec := do(h, http.MethodPost, "/v1/volumes", `{"id":"vol1","poolId":"vp","sizeBytes":300}`)
52		if rec.Code != http.StatusOK {
53			t.Fatalf("retry status = %d %s", rec.Code, rec.Body.String())
54		}
55		v := decodeBody(t, rec)
56		if v["generation"].(float64) != 0 || v["binding"] != nil {
57			t.Fatalf("retry view = %v", v)
58		}
59		p := decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/vp", ""))
60		if p["allocatedBytes"].(float64) != 300 {
61			t.Fatalf("allocated after retry = %v", p["allocatedBytes"])
62		}
63	
64		// Different parameters: 409 volume_exists.
65		wantError(t, do(h, http.MethodPost, "/v1/volumes", `{"id":"vol1","poolId":"vp","sizeBytes":301}`),
66			http.StatusConflict, "volume_exists")
67		wantError(t, do(h, http.MethodPost, "/v1/volumes", `{"id":"vol1","poolId":"other","sizeBytes":300}`),
68			http.StatusConflict, "volume_exists")
69	
70		// Unknown pool: 404 pool_not_found.
71		wantError(t, do(h, http.MethodPost, "/v1/volumes", `{"id":"vol2","poolId":"nope","sizeBytes":1}`),
72			http.StatusNotFound, "pool_not_found")
73	
74		// Insufficient capacity leaves no volume and no allocation behind.
75		wantError(t, do(h, http.MethodPost, "/v1/volumes", `{"id":"big","poolId":"vp","sizeBytes":701}`),
76			http.StatusConflict, "insufficient_capacity")
77		rec = do(h, http.MethodGet, "/v1/volumes", "")
78		items := decodeBody(t, rec)["items"].([]any)
79		if len(items) != 1 {
80			t.Fatalf("partial volume after failure: %v", items)
81		}
82		p = decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/vp", ""))
83		if p["allocatedBytes"].(float64) != 300 {
84			t.Fatalf("partial allocation after failure: %v", p["allocatedBytes"])
85		}
86	
87		// Exactly the remaining capacity fits.
88		createVol(t, h, `{"id":"exact","poolId":"vp","sizeBytes":700}`)
89		wantError(t, do(h, http.MethodPost, "/v1/volumes", `{"id":"one","poolId":"vp","sizeBytes":1}`),
90			http.StatusConflict, "insufficient_capacity")
91	}
92	
93	func TestCreateVolumeInvalidRequests(t *testing.T) {
94		h := Handler()
95		createPool(t, h, volPool)
96		for name, body := range map[string]string{
97			"unknown field":  `{"id":"v","poolId":"vp","sizeBytes":1,"extra":1}`,
98			"missing id":     `{"poolId":"vp","sizeBytes":1}`,
99			"missing pool":   `{"id":"v","sizeBytes":1}`,
100			"missing size":   `{"id":"v","poolId":"vp"}`,
101			"bad volume id":  `{"id":"bad id","poolId":"vp","sizeBytes":1}`,
102			"bad pool id":    `{"id":"v","poolId":"bad pool","sizeBytes":1}`,
103			"zero size":      `{"id":"v","poolId":"vp","sizeBytes":0}`,
104			"negative size":  `{"id":"v","poolId":"vp","sizeBytes":-1}`,
105			"float size":     `{"id":"v","poolId":"vp","sizeBytes":1.5}`,
106			"string size":    `{"id":"v","poolId":"vp","sizeBytes":"1"}`,
107			"malformed json": `{"id":"v",`,
108		} {
109			t.Run(name, func(t *testing.T) {
110				wantError(t, do(h, http.MethodPost, "/v1/volumes", body), http.StatusBadRequest, "invalid_request")
111			})
112		}
113		// No partial state from any failed create.
114		if rec := do(h, http.MethodGet, "/v1/volumes", ""); rec.Body.String() != "{\"items\":[]}\n" {
115			t.Fatalf("partial state: %s", rec.Body.String())
116		}
117	}
118	
119	func TestListAndGetVolumes(t *testing.T) {
120		h := Handler()
121		createPool(t, h, volPool)
122		if rec := do(h, http.MethodGet, "/v1/volumes", ""); rec.Body.String() != "{\"items\":[]}\n" {
123			t.Fatalf("empty list = %q", rec.Body.String())
124		}
