151		createVol(t, h, `{"id":"vol1","poolId":"vp","sizeBytes":10}`)
152	
153		put := func(body string) *httptest.ResponseRecorder {
154			return do(h, http.MethodPut, "/v1/volumes/vol1/binding", body)
155		}
156	
157		// Bind node-a at generation 0: 200, binding set, generation bumps to 1.
158		rec := put(`{"nodeId":"node-a","expectedGeneration":0}`)
159		if rec.Code != http.StatusOK {
160			t.Fatalf("bind status = %d %s", rec.Code, rec.Body.String())
161		}
162		v := decodeBody(t, rec)
163		if v["generation"].(float64) != 1 {
164			t.Fatalf("generation after bind = %v", v["generation"])
165		}
166		binding := v["binding"].(map[string]any)
167		if binding["nodeId"] != "node-a" {
168			t.Fatalf("binding = %v", binding)
169		}
170	
171		// Same node, matching generation: idempotent 200 without increment.
172		rec = put(`{"nodeId":"node-a","expectedGeneration":1}`)
173		if rec.Code != http.StatusOK {
174			t.Fatalf("rebind same status = %d", rec.Code)
175		}
176		if decodeBody(t, rec)["generation"].(float64) != 1 {
177			t.Fatalf("generation changed on idempotent rebind: %s", rec.Body.String())
178		}
179	
180		// Rebind to another node: 409 volume_already_bound.
181		wantError(t, put(`{"nodeId":"node-b","expectedGeneration":1}`), http.StatusConflict, "volume_already_bound")
182	
183		// Stale generation: 409 stale_generation.
184		wantError(t, put(`{"nodeId":"node-a","expectedGeneration":0}`), http.StatusConflict, "stale_generation")
185		wantError(t, put(`{"nodeId":"node-b","expectedGeneration":0}`), http.StatusConflict, "stale_generation")
186	
187		// Bound volume cannot be deleted.
188		wantError(t, do(h, http.MethodDelete, "/v1/volumes/vol1", ""), http.StatusConflict, "volume_in_use")
189	
190		// Unbind with the correct generation: 204, generation bumps to 2.
191		rec = do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=1", "")
192		if rec.Code != http.StatusNoContent {
193			t.Fatalf("unbind status = %d %s", rec.Code, rec.Body.String())
194		}
195		v = decodeBody(t, do(h, http.MethodGet, "/v1/volumes/vol1", ""))
196		if v["generation"].(float64) != 2 || v["binding"] != nil {
197			t.Fatalf("volume after unbind = %v", v)
198		}
199	
200		// Unbinding an already-unbound volume at the matching generation: 204
201		// without bumping the generation.
202		rec = do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=2", "")
203		if rec.Code != http.StatusNoContent {
204			t.Fatalf("repeat unbind = %d", rec.Code)
205		}
206		v = decodeBody(t, do(h, http.MethodGet, "/v1/volumes/vol1", ""))
207		if v["generation"].(float64) != 2 {
208			t.Fatalf("generation changed after unbound unbind: %v", v["generation"])
209		}
210	
211		// Stale generation on unbind.
212		wantError(t, do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=0", ""),
213			http.StatusConflict, "stale_generation")
214	
215		// Once unbound, it can be rebound at the new generation, then deleted
216		// only after a final unbind.
217		rec = put(`{"nodeId":"node-c","expectedGeneration":2}`)
218		if rec.Code != http.StatusOK || decodeBody(t, rec)["generation"].(float64) != 3 {
219			t.Fatalf("rebind after unbind = %d %s", rec.Code, rec.Body.String())
220		}
221		if rec = do(h, http.MethodDelete, "/v1/volumes/vol1/binding?expectedGeneration=3", ""); rec.Code != http.StatusNoContent {
222			t.Fatalf("final unbind = %d", rec.Code)
223		}
224		if rec = do(h, http.MethodDelete, "/v1/volumes/vol1", ""); rec.Code != http.StatusNoContent {
225			t.Fatalf("delete volume = %d %s", rec.Code, rec.Body.String())
226		}
227		wantError(t, do(h, http.MethodGet, "/v1/volumes/vol1", ""), http.StatusNotFound, "volume_not_found")
