229		// Capacity is returned to the pool.
230		p := decodeBody(t, do(h, http.MethodGet, "/v1/storage-pools/vp", ""))
231		if p["allocatedBytes"].(float64) != 0 || p["availableBytes"].(float64) != 1000 {
232			t.Fatalf("pool after delete = %v", p)
233		}
234	}
