350		var created, rejected int64
351		var mu sync.Mutex
352		wg.Add(goroutines)
353		for i := 0; i < goroutines; i++ {
354			go func(i int) {
355				defer wg.Done()
356				body := fmt.Sprintf(`{"id":"v%d","poolId":"cp","sizeBytes":10}`, i)
357				rec := do(h, http.MethodPost, "/v1/volumes", body)
358				mu.Lock()
359				switch rec.Code {
360				case http.StatusCreated:
361					created++
362				case http.StatusConflict:
363					rejected++
364				default:
365					t.Errorf("unexpected status %d", rec.Code)
366				}
367				mu.Unlock()
368			}(i)
369		}
370		wg.Wait()
371		if created != 10 || rejected != 40 {
372			t.Fatalf("created=%d rejected=%d, want 10/40", created, rejected)
373		}
