118	}
119	
120	// createSnapshot handles POST /v1/volumes/{volumeId}/snapshots.
121	func (s *store) createSnapshot(w http.ResponseWriter, r *http.Request, volumeID string) {
122		var in createSnapshotInput
123		if !decodeRequest(r, &in) {
124			writeError(w, http.StatusBadRequest, "invalid_request")
125			return
126		}
127		if !validID(volumeID) || !validID(in.ID) || in.ExpectedGeneration == nil || *in.ExpectedGeneration < 0 {
128			writeError(w, http.StatusBadRequest, "invalid_request")
129			return
130		}
131		expected := *in.ExpectedGeneration
132	
133		s.mu.Lock()
134		defer s.mu.Unlock()
135		// A retry of the same id wins its idempotency/conflict check before the
136		// source is looked up, so deleting the source after a successful snapshot
137		// keeps the retry returning 200.
138		if existing, dup := s.snapshots[in.ID]; dup {
139			if existing.sourceVolumeID == volumeID && existing.sourceGeneration == expected {
140				writeJSON(w, http.StatusOK, existing.view())
141				return
142			}
143			writeError(w, http.StatusConflict, "snapshot_exists")
144			return
145		}
146		v, ok := s.volumes[volumeID]
147		if !ok {
148			writeError(w, http.StatusNotFound, "volume_not_found")
149			return
150		}
151		if v.binding != "" {
152			writeError(w, http.StatusConflict, "volume_in_use")
153			return
154		}
155		if v.generation != expected {
156			writeError(w, http.StatusConflict, "stale_generation")
157			return
158		}
159		p := s.pools[v.poolID]
160		// The store lock makes the capacity check and charge atomic, so
161		// concurrent snapshots can never overcommit the pool.
162		if p.allocated() > p.rawCapacity-v.sizeBytes {
163			writeError(w, http.StatusConflict, "insufficient_capacity")
164			return
165		}
166		snap := &snapshot{
167			id:               in.ID,
168			sourceVolumeID:   volumeID,
169			poolID:           v.poolID,
170			sizeBytes:        v.sizeBytes,
171			sourceGeneration: v.generation,
172		}
173		s.snapshots[in.ID] = snap
174		p.snapshotBytes += v.sizeBytes
175		writeJSON(w, http.StatusCreated, snap.view())
176	}
177	
178	func (s *store) deleteSnapshot(w http.ResponseWriter, id string) {
179		if !validID(id) {
180			writeError(w, http.StatusBadRequest, "invalid_request")
181			return
182		}
183		s.mu.Lock()
184		defer s.mu.Unlock()
185		snap, ok := s.snapshots[id]
186		if !ok {
187			writeError(w, http.StatusNotFound, "snapshot_not_found")
188			return
189		}
190		s.pools[snap.poolID].snapshotBytes -= snap.sizeBytes
191		delete(s.snapshots, id)
192		w.WriteHeader(http.StatusNoContent)
193	}
194	
195	// createClone handles POST /v1/snapshots/{id}/clones.
196	func (s *store) createClone(w http.ResponseWriter, r *http.Request, snapshotID string) {
197		var in createCloneInput
198		if !decodeRequest(r, &in) {
199			writeError(w, http.StatusBadRequest, "invalid_request")
200			return
201		}
202		if !validID(snapshotID) || !validID(in.ID) || !validID(in.PoolID) {
203			writeError(w, http.StatusBadRequest, "invalid_request")
204			return
205		}
206	
207		s.mu.Lock()
208		defer s.mu.Unlock()
209		snap, ok := s.snapshots[snapshotID]
210		if !ok {
211			writeError(w, http.StatusNotFound, "snapshot_not_found")
212			return
213		}
214		// A clone is an ordinary volume, so its id shares the global volume
215		// namespace. The volume-id conflict check runs first: a matching retry
216		// returns 200 even if the target pool was later removed, and an id owned
217		// by any other creation surfaces 409 volume_exists.
218		if existing, dup := s.volumes[in.ID]; dup {
219			if existing.cloneSource == snapshotID && existing.poolID == in.PoolID {
220				writeJSON(w, http.StatusOK, existing.view())
221				return
222			}
223			writeError(w, http.StatusConflict, "volume_exists")
224			return
225		}
226		target, ok := s.pools[in.PoolID]
227		if !ok {
228			writeError(w, http.StatusNotFound, "pool_not_found")
229			return
230		}
231		if target.allocated() > target.rawCapacity-snap.sizeBytes {
232			writeError(w, http.StatusConflict, "insufficient_capacity")
233			return
234		}
235		v := &volume{id: in.ID, poolID: in.PoolID, sizeBytes: snap.sizeBytes, cloneSource: snapshotID}
236		s.volumes[in.ID] = v
237		target.volumeBytes += snap.sizeBytes
238		writeJSON(w, http.StatusCreated, v.view())
239	}

